const keyMappedObject = {
  rage_tap: 'rageTap',
  rage_quit: 'rage_quit',
  session_crashed: 'session_crashed',
  session_has_video: 'session_has_video',
  session_analyzed_by_ai: 'session_analyzed_by_ai',
  ui_freeze: 'UI Freeze',
};

// const extraLabelKeys = ['session_with_notes', 'session_has_video', 'session_is_viewed'];
const extraCustomLabelKeys = ['custom_label', 'user_custom_label'];

const Quickbar = ({ loadTable = null, megaFilterRestyle = false, renderRef = null }) => {
  const dispatch = useDispatch();
  const isWebSDK = useIsAppType( 'web' );
  const { aiSessionFeatureAllowed } = useRestrictionContext();

  const { customLabels, 
    handleLabel, 
    sessionSegment, 
    labelSearch, 
    setLabelSearch, 
    filteredSessionLabels, 
    filteredUserLabels, 
    selectedLabels,
    setSelectedLabels,
    resetSearch,
    compareLabels,
    getLabelTypeFromValue,
  } = useCustomLabels();
  const [selectedCustomLabelTab, setSelectedCustomLabelTab] = useState('session');

  const [selectedMenu, setSelectedMenu] = useState([])
  const [dropdownOpen, setDropdownOpen] = useState(false)
 const {
    urlReducer: { parentType, issueid, issueType, issuepage, appId, starttime, sessionid, issuedetailpage, sessionpage },
   } = useSelector((state) => state);
  const selectedMenuFromQuickfilter = React.useMemo(() => (sessionSegment || []).map((segment) => {
    const keyMappedObjectValues = Object.values(keyMappedObject)
    const selectedObjectValues = [...keyMappedObjectValues]; 
    return selectedObjectValues.find((value) => value === segment.attribute || value === segment.value[0] || segment.value[0] === "rageTap" || segment.attribute === "custom_label")
  }).filter((el) => el !== undefined), [sessionSegment])

  useEffect(() => {
    const filteredSessionSegment = sessionSegment.filter(item =>
      ['event_name', 'custom_label', 'user_custom_label', 'session_crashed', 'rage_quit', 'session_has_video', 'session_analyzed_by_ai'].includes(item.attribute))
    const filterValue = [];
    if (filteredSessionSegment?.length > 0) {
      filteredSessionSegment.map(segment => {
        if (segment.attribute === 'custom_label' || segment.attribute === 'user_custom_label') {
            segment.value.map(item => filterValue.push(item));
        }
        if (segment.attribute === 'event_name') {
          segment.value.map(item =>
            ['rageTap', 'UI Freeze'].includes(item) ? filterValue.push(item) : [])
        }
        if (segment.attribute === 'session_crashed' || segment.attribute === 'rage_quit' || segment.attribute === 'session_has_video' || segment.attribute === 'session_analyzed_by_ai' ) {
          segment.value === 'True' ? filterValue.push(segment.attribute) : []
        }
        // if (extraLabelKeys.includes(segment.attribute)) {
        //   filterValue.push(segment.attribute)
        // }
        return uniq(filterValue);
      })
      setSelectedMenu(filterValue.map((v) => invert(keyMappedObject)[v] || v));
    } else {
      setSelectedMenu(filterValue);
    }
  }, [sessionSegment])

  const handleClearFilter = React.useCallback(() => {
    let newSessionSegment = sessionSegment || []
    selectedMenuFromQuickfilter.forEach((el) => {
      const val = el;
      newSessionSegment = newSessionSegment.filter((segment) => segment.attribute !== val && segment.value[0] !== val && !extraCustomLabelKeys.includes(segment.attribute))
    })

    dispatch(
      addSegmentV2(
        newSessionSegment.length > 0 ? newSessionSegment : undefined,
        'session-filter'
      )
    )
    dispatch(callSessionStatisticsAPI());
  }, [sessionSegment, dispatch, selectedMenuFromQuickfilter])

  const handleFilter = React.useCallback(({ key }) => {
    dispatch(addSessionId([]))
    let segment
    let newSelected = [...selectedMenu]
    let segmentValue = sessionSegment || []

    const addingFilter = !newSelected.includes(key)

    if (addingFilter) {
      newSelected = [...newSelected, key];
      setSelectedMenu(newSelected);
      if (key === 'session_crashed' || key === 'rage_quit' || key === 'session_has_video' || key === 'session_analyzed_by_ai') {
        segment = {
          "attribute": key,
          "operator": "equal",
          "value": "True",
          "table": "session"
        }
      } else {
        const value = keyMappedObject[key]
        segment = { attribute: 'event_name', operator: 'in', value: [value], table: 'event' }
      }
      const oldSegmentValue = [ ...segmentValue ]
      segmentValue.push(segment);

      dispatch(
        trackPageViews(null, {
          eventName: 'apply_quick_filter',
          track_type: 'event',
          eventProperty: {
            type: 'predefined',
            name: key,
            featureFlagQuickbar: true,
            oldSetting: oldSegmentValue,
            newSetting: segmentValue,
          },
        })
      )
    } else {
      setSelectedMenu(selectedMenu.filter(item => item !== key));
      const labelKey = keyMappedObject[key];
      const oldSegmentValue = [ ...segmentValue ]
      if (key === 'session_crashed' || key === 'rage_quit' || key === 'session_has_video' || key === 'session_analyzed_by_ai') {
        segmentValue = sessionSegment.filter((obj) => obj.attribute !== labelKey);
      } else {
        segmentValue = sessionSegment.filter((obj) => obj.value[0] !== labelKey);
      }

      dispatch(
        trackPageViews(null, {
          eventName: 'quick_filter_removed',
          track_type: 'event',
          eventProperty: {
            type: 'predefined',
            name: key,
            featureFlagQuickbar: true,
            oldSetting: oldSegmentValue,
            newSetting: segmentValue,
          },
        })
      )
    }

    if (segmentValue.length === 0) {
      handleClearFilter()
    } else {
      dispatch(
        addSegmentV2(
          segmentValue.length > 0 ? segmentValue : undefined,
          'session-filter'
        )
      )
    }
    dispatch(callSessionStatisticsAPI())
    // **HOT FIX: due to some reason for aiSessionsList, url route is not getting updated. This following code is a workaround to fix that
    if(parentType === 'aiSessionsList') {
        applyAiSessionsPageApi({
            appId,
            sessionid,
            sessionpage,
            starttime
          }, segmentValue);
    }

    if (typeof loadTable === 'function') {
      loadTable();
    }
  }, [dispatch, selectedMenu, sessionSegment, parentType, loadTable, handleClearFilter, appId, sessionid, sessionpage, starttime]);

  const getSelectedMenuByType = React.useCallback((type) => {
    const selectedMenuByType = selectedMenu.filter((item) => {
      if (type === 'session' && getLabelTypeFromValue(item) === 'session') {
        return true
      }
      if (type === 'user' && getLabelTypeFromValue(item) === 'user') {
        return true
      }
      return false
    })
    return selectedMenuByType
  }, [getLabelTypeFromValue, selectedMenu])

  const handleCustomLabelsApplyClick = React.useCallback(() => {
    const newSessionSelectedMenu = [...new Set([...getSelectedMenuByType('session'), ...selectedLabels.sessionLabels])]
    const newUserSelectedMenu = [...new Set([...getSelectedMenuByType('user'), ...selectedLabels.userLabels])]
    handleLabel(newSessionSelectedMenu, newUserSelectedMenu, loadTable)
    setDropdownOpen( false )
  }, [getSelectedMenuByType, handleLabel, loadTable, selectedLabels.sessionLabels, selectedLabels.userLabels])

  const handleLabelSearch = useCallback((e) => {
    const { value } = e.target;
    if(selectedCustomLabelTab === 'session') {
      setLabelSearch({
        ...labelSearch,
        sessionLabels: value
      })
    } else {
      setLabelSearch({
        ...labelSearch,
        userLabels: value
      })
    }
  }, [labelSearch, selectedCustomLabelTab, setLabelSearch])

  const handleVisibleChange = React.useCallback((visible) => {
    setDropdownOpen(visible);
    if (!visible) {
      setSelectedLabels({
        sessionLabels: [],
        userLabels: [],
      });
    }
  }, [setSelectedLabels]);

  const showClearButton = React.useMemo(() => ( !megaFilterRestyle && sessionSegment || []).length > 0, [sessionSegment])
  const filteredArr = useMemo(
    () =>
      sessionSegment.filter((obj) =>
        extraCustomLabelKeys.includes(obj.attribute)
      ),
    [sessionSegment]
  );
  const customLabelsCount = React.useMemo(
    () => uniq(flatten(filteredArr.map((el) => el.value))).length,
    [filteredArr]
  );

  const handleCustomLabelClick = React.useCallback((key) => {
    const selectedKeys = [...selectedMenu, ...selectedLabels.sessionLabels, ...selectedLabels.userLabels]
    const keyAlreadyExists = selectedKeys.includes(key)
    if (keyAlreadyExists) {
      setSelectedLabels({
        sessionLabels: selectedLabels.sessionLabels.filter((item) => item !== key),
        userLabels: selectedLabels.userLabels.filter((item) => item !== key),
      })
      setSelectedMenu(selectedMenu.filter((item) => item !== key))
    } else if (selectedCustomLabelTab === 'session') {
      setSelectedLabels({
        sessionLabels: [...selectedLabels.sessionLabels, key],
        userLabels: selectedLabels.userLabels,
      })
    } else {
      setSelectedLabels({
        sessionLabels: selectedLabels.sessionLabels,
        userLabels: [...selectedLabels.userLabels, key],
      })
    }
  }, [selectedLabels, selectedMenu, setSelectedLabels, selectedCustomLabelTab])

  useEffect(() => {
    if ( !dropdownOpen ) {
      filteredSessionLabels?.sort((a, b) =>
        compareLabels(selectedMenu, a, b)
      );
      filteredUserLabels?.sort((a, b) => compareLabels(selectedMenu, a, b));
      resetSearch();
    }
  }, [compareLabels, customLabels, dropdownOpen, filteredSessionLabels, filteredUserLabels, resetSearch, selectedMenu])

  const labelTabs = [
    {
        key: 'session',
        name: 'Session label',
        options: filteredSessionLabels, // includes filtered labels
        showSearch: true,
    },
    {
        key: 'user',
        name: 'User label',
        options: filteredUserLabels, // includes filtered labels
        showSearch: true,
    }
  ]

  const handleCustomLabelTabChange = (key) => {
    setSelectedCustomLabelTab(key)
  }

  const tooltipOffset = megaFilterRestyle ? { offset: [ 0, -5 ] } : undefined

  return (
    <>
      <GlobalStyles />
      <Wrapper data-megaFilterRestyle={ megaFilterRestyle }>
        <PillMenu onClick={handleFilter} selectedKeys={selectedMenu} multiple data-megaFilterRestyle={ megaFilterRestyle }>
          { megaFilterRestyle && aiSessionFeatureAllowed && (
            <Pill data-megaFilterRestyle={ megaFilterRestyle } key="session_analyzed_by_ai" data-intercom-target="session_analyzed_by_ai">
              <Tooltip
                placement="bottomLeft"
                overlayClassName="tooltip-new-design"
                align={ tooltipOffset }
                title={
                  <>
                    Sessions analyzed by AI.
                  </>
                }
              >
                <IconAIAnalyzed height={16} width={16} />
                <h5>AI-analyzed</h5>
              </Tooltip>
            </Pill>
          ) }
          {
            isWebSDK ? (
              <Pill data-megaFilterRestyle={ megaFilterRestyle } key="rage_tap" data-intercom-target="rage_taps">
                <Tooltip
                  placement="bottomLeft"
                  overlayClassName="tooltip-new-design"
                  align={ tooltipOffset }
                  title={
                    <>
                      Quick, repeated taps indicating user frustration.
                    </>
                  }
                >
                  <IconRageTaps height={16} width={16} />
                  <h5>Rage tap</h5>
                </Tooltip>
              </Pill>
            ) : (
              <>
                <Pill data-megaFilterRestyle={ megaFilterRestyle } key="session_has_video" data-intercom-target="session_has_video">
                  <Tooltip
                    placement="bottomLeft"
                    overlayClassName="tooltip-new-design"
                    align={ tooltipOffset }
                    title={
                      <>
                        Sessions containing video with user interactions.
                      </>
                    }
                  >
                    <IconWithVideo height={16} width={16} />
                    <h5>With video</h5>
                  </Tooltip>
                </Pill>
                <Pill data-megaFilterRestyle={ megaFilterRestyle } key="rage_tap" data-intercom-target="rage_taps">
                  <Tooltip
                    placement="bottomLeft"
                    overlayClassName="tooltip-new-design"
                    align={ tooltipOffset }
                    title={
                      <>
                        Quick, repeated taps indicating user frustration.
                      </>
                    }
                  >
                    <IconRageTaps height={16} width={16} />
                    <h5>Rage tap</h5>
                  </Tooltip>
                </Pill>
                <Pill data-megaFilterRestyle={ megaFilterRestyle } key="rage_quit" data-intercom-target="rage_quits">
                  <Tooltip
                    placement="bottomLeft"
                    overlayClassName="tooltip-new-design"
                    align={ tooltipOffset }
                    title={<>Exit that happened immediately after rage taps.</>}
                  >
                    <IconRageQuits height={16} width={16} />
                    <h5>Rage quit</h5>
                  </Tooltip>
                </Pill>
                <Pill data-megaFilterRestyle={ megaFilterRestyle } key="session_crashed" data-intercom-target="session_crashed">
                  <Tooltip
                    placement="bottomLeft"
                    overlayClassName="tooltip-new-design"
                    align={ tooltipOffset }
                    title={<>Unexpected exit caused by an unhandled exception.</>}
                  >
                    <IconAppCrash height={16} width={16} />
                    <h5>App crash</h5>
                  </Tooltip>
                </Pill>
                <Pill data-megaFilterRestyle={ megaFilterRestyle } key="ui_freeze" data-intercom-target="ui_freeze">
                  <Tooltip
                    placement="bottomLeft"
                    overlayClassName="tooltip-new-design"
                    align={ tooltipOffset }
                    title={
                      <>
                        Temporary UI unresponsiveness.
                      </>
                    }
                  >
                    <IconUIFreeze height={16} width={16} />
                    <h5>UI freeze</h5>
                  </Tooltip>
                </Pill>
                {/* <Pill key="favourite" data-intercom-target="favourite">
                  <PillIcon src="/static/sessions/favourites.svg" />
                  <h5>Favourites</h5>
                </Pill> */}     
              </>
            )
          }
          <Dropdown
            overlay={
              <LabelsDropdownOverlay
                tabs={labelTabs}
                selectedKeys={[
                  ...selectedMenu,
                  ...selectedLabels.sessionLabels,
                  ...selectedLabels.userLabels,
                ]}
                handleItemClicked={handleCustomLabelClick}
                handleApply={handleCustomLabelsApplyClick}
                handleTabChange={handleCustomLabelTabChange}
                searchInput={{
                  placeholder: 'Search labels',
                  value:
                    selectedCustomLabelTab === 'session'
                      ? labelSearch.sessionLabels
                      : labelSearch.userLabels,
                  onChange: handleLabelSearch,
                }}
              />
            }
            trigger={['click']}
            onVisibleChange={handleVisibleChange}
            overlayClassName="custom-labels-dropdown"
            getPopupContainer={ renderRef?.current ? () => renderRef.current : undefined }
          >
            <Tooltip
              placement="bottomLeft"
              overlayClassName="tooltip-new-design"
              title="Filter sessions by session or user labels."
            >
              <PillButton
                selected={customLabelsCount > 0}
                size="small"
                data-intercom-target="Quick Filter"
              >
                {customLabelsCount ? <span>{customLabelsCount}</span> : null}
                <h5>Labels</h5>
                <IconCaretDown height={16} width={16} />
              </PillButton>
            </Tooltip>
          </Dropdown>
          {showClearButton && (
            <ButtonClear onClick={handleClearFilter}>Clear all</ButtonClear>
          )}
        </PillMenu>
      </Wrapper>
    </>
  );
}

export default React.memo(Quickbar)